/**
 * Unicode predicates that mirror the CPython helpers used by `int()` and `repr()`.
 *
 * CPython does not restrict `int("...")` to ASCII: any character whose Unicode
 * general category is Nd carries a decimal value, and `str.strip()` (applied by
 * `int()` before parsing) removes every character for which `str.isspace()` is
 * true.  These helpers reproduce those two predicates plus `str.isprintable()`,
 * which `repr()` needs in order to decide what to escape.
 */

/**
 * One entry per contiguous run of ten decimal digits in the Unicode database
 * (the code point of each family's zero).  Unicode guarantees a decimal digit
 * family occupies exactly ten consecutive code points, so the value of a digit
 * is `codePoint - base`.
 */
const DECIMAL_ZERO_BASES = [
  0x30, 0x660, 0x6f0, 0x7c0, 0x966, 0x9e6, 0xa66, 0xae6, 0xb66, 0xbe6,
  0xc66, 0xce6, 0xd66, 0xde6, 0xe50, 0xed0, 0xf20, 0x1040, 0x1090, 0x17e0,
  0x1810, 0x1946, 0x19d0, 0x1a80, 0x1a90, 0x1b50, 0x1bb0, 0x1c40, 0x1c50,
  0xa620, 0xa8d0, 0xa900, 0xa9d0, 0xa9f0, 0xaa50, 0xabf0, 0xff10, 0x104a0,
  0x10d30, 0x11066, 0x110f0, 0x11136, 0x111d0, 0x112f0, 0x11450, 0x114d0,
  0x11650, 0x116c0, 0x11730, 0x118e0, 0x11950, 0x11c50, 0x11d50, 0x11da0,
  0x11f50, 0x16a60, 0x16ac0, 0x16b50, 0x1d7ce, 0x1d7d8, 0x1d7e2, 0x1d7ec,
  0x1d7f6, 0x1e140, 0x1e2f0, 0x1e4f0, 0x1e950, 0x1fbf0,
];

/** Code points `Py_UNICODE_ISSPACE` accepts that are outside the Z* categories. */
const EXTRA_SPACE_CODE_POINTS = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20, 0x85,
]);

/** Zs plus LINE SEPARATOR (U+2028) and PARAGRAPH SEPARATOR (U+2029). */
const SPACE_SEPARATOR = new RegExp('^[\\p{Zs}\\u2028\\u2029]$', 'u');

/** Categories for which `str.isprintable()` is false (ASCII space is the one exception). */
const NON_PRINTABLE = buildNonPrintableMatcher();

function buildNonPrintableMatcher() {
  // `\p{Cn}` (unassigned) is not accepted by every engine; degrade gracefully.
  try {
    return new RegExp('^[\\p{Cc}\\p{Cf}\\p{Cs}\\p{Co}\\p{Cn}\\p{Zl}\\p{Zp}\\p{Zs}]$', 'u');
  } catch {
    return new RegExp('^[\\p{Cc}\\p{Cf}\\p{Cs}\\p{Co}\\p{Zl}\\p{Zp}\\p{Zs}]$', 'u');
  }
}

/**
 * Decimal value of a code point, or -1 when it is not a decimal digit.
 * Equivalent to CPython's `Py_UNICODE_TODECIMAL`.
 */
export function decimalDigitValue(codePoint) {
  let low = 0;
  let high = DECIMAL_ZERO_BASES.length - 1;
  while (low <= high) {
    const mid = (low + high) >> 1;
    const base = DECIMAL_ZERO_BASES[mid];
    if (codePoint < base) high = mid - 1;
    else if (codePoint >= base + 10) low = mid + 1;
    else return codePoint - base;
  }
  return -1;
}

/** `str.isspace()` for a single code point. */
export function isPythonSpace(codePoint) {
  return (
    EXTRA_SPACE_CODE_POINTS.has(codePoint) ||
    SPACE_SEPARATOR.test(String.fromCodePoint(codePoint))
  );
}

/** `str.isprintable()` for a single code point. */
export function isPythonPrintable(codePoint) {
  if (codePoint === 0x20) return true;
  return !NON_PRINTABLE.test(String.fromCodePoint(codePoint));
}
