/**
 * Bech32 string codec: the raw `hrp` + separator + data-with-checksum format,
 * independent of any segwit interpretation.
 */

import { CHARSET, charsetAt, charsetIndexOf } from './charset.mjs';
import { bech32CreateChecksum, bech32VerifyChecksum } from './checksum.mjs';

const MIN_CODE_POINT = 33;
const MAX_CODE_POINT = 126;
const SEPARATOR = '1';
const CHECKSUM_LENGTH = 6;

/** `bech32_encode(hrp, data)`; may raise `IndexError` for out-of-range values. */
export function bech32Encode(hrp, data) {
  const combined = [...data, ...bech32CreateChecksum(hrp, data)];
  let encoded = '';
  for (const value of combined) encoded += charsetAt(value);
  return hrp + SEPARATOR + encoded;
}

/**
 * `bech32_decode(bech)` -> `[hrp, data]`, or `[null, null]` when the string is
 * not a well-formed Bech32 string with a valid checksum.
 */
export function bech32Decode(bech) {
  for (const character of bech) {
    const codePoint = character.codePointAt(0);
    if (codePoint < MIN_CODE_POINT || codePoint > MAX_CODE_POINT) return [null, null];
  }
  // Mixed case is not allowed; the range check above guarantees pure ASCII here.
  if (bech.toLowerCase() !== bech && bech.toUpperCase() !== bech) return [null, null];

  const normalized = bech.toLowerCase();
  const position = normalized.lastIndexOf(SEPARATOR);
  if (position < 1 || position + 1 + CHECKSUM_LENGTH > normalized.length) {
    return [null, null];
  }

  const payload = normalized.slice(position + 1);
  for (const character of payload) {
    if (!CHARSET.includes(character)) return [null, null];
  }

  const hrp = normalized.slice(0, position);
  const data = [...payload].map((character) => BigInt(charsetIndexOf(character)));
  if (!bech32VerifyChecksum(hrp, data)) return [null, null];

  return [hrp, data.slice(0, -CHECKSUM_LENGTH)];
}
===== checksum.mjs =====
/**
 * The BCH checksum machinery behind Bech32.
 *
 * Every value is a BigInt so the arithmetic matches Python's unbounded integers:
 * a witness version outside 0..31 still flows through `bech32_polymod`, where
 * two's-complement XOR over negative values must agree bit for bit with CPython
 * before the result is rejected downstream.
 */

const GENERATOR = [0x3b6a57b2n, 0x26508e6dn, 0x1ea119fan, 0x3d4233ddn, 0x2a1462b3n];

const LOW_25_BITS = 0x1ffffffn;
const FIVE_BITS = 31n;

/** `bech32_polymod`. */
export function bech32Polymod(values) {
  let checksum = 1n;
  for (const value of values) {
    const top = checksum >> 25n;
    checksum = ((checksum & LOW_25_BITS) << 5n) ^ value;
    for (let bit = 0; bit < 5; bit += 1) {
      if ((top >> BigInt(bit)) & 1n) checksum ^= GENERATOR[bit];
    }
  }
  return checksum;
}

/** `bech32_hrp_expand`: high bits of the HRP, a zero, then the low bits. */
export function bech32HrpExpand(hrp) {
  const high = [];
  const low = [];
  for (const character of hrp) {
    const codePoint = BigInt(character.codePointAt(0));
    high.push(codePoint >> 5n);
    low.push(codePoint & FIVE_BITS);
  }
  return [...high, 0n, ...low];
}

/** `bech32_verify_checksum`. */
export function bech32VerifyChecksum(hrp, data) {
  return bech32Polymod([...bech32HrpExpand(hrp), ...data]) === 1n;
}

/** `bech32_create_checksum`: the six trailing data values. */
export function bech32CreateChecksum(hrp, data) {
  const values = [...bech32HrpExpand(hrp), ...data, 0n, 0n, 0n, 0n, 0n, 0n];
  const polymod = bech32Polymod(values) ^ 1n;
  const checksum = [];
  for (let position = 0; position < 6; position += 1) {
    checksum.push((polymod >> (5n * BigInt(5 - position))) & FIVE_BITS);
  }
  return checksum;
}
===== convertbits.mjs =====
/**
 * `convertbits`: general power-of-two base conversion over a list of integers.
 *
 * Values stay BigInt so that an out-of-range witness program byte is rejected by
 * the same `value >> frombits` test Python applies, whatever its magnitude.
 * A rejected input yields `null`, mirroring the Python return value.
 */

export function convertBits(data, fromBits, toBits, pad = true) {
  const from = BigInt(fromBits);
  const to = BigInt(toBits);
  const maxValue = (1n << to) - 1n;
  const maxAccumulator = (1n << (from + to - 1n)) - 1n;

  let accumulator = 0n;
  let bits = 0n;
  const result = [];

  for (const value of data) {
    if (value < 0n || (value >> from) !== 0n) return null;
    accumulator = ((accumulator << from) | value) & maxAccumulator;
    bits += from;
    while (bits >= to) {
      bits -= to;
      result.push((accumulator >> bits) & maxValue);
    }
  }

  if (pad) {
    if (bits !== 0n) result.push((accumulator << (to - bits)) & maxValue);
  } else if (bits >= from || ((accumulator << (to - bits)) & maxValue) !== 0n) {
    return null;
  }

  return result;
}

